# port scan plugin
yakit.AutoInitYakit()

// 准备发送的报文模版 

PacketGet = `GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 6.1; Win64; x64; rv:47.0) Gecko/20100101 Firefox/47.0

`


PacketPost = `POST /cu.html HTTP/1.1
Host: {{params(target)}}
Accept: */*
Accept-Encoding: gzip
Content-Length: 2
Content-Type: application/json;charset=utf-8
User-Agent: Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0)

{{params(payload)}}
`
//漏洞检测规则函数 
rules = []
addRule = func(packet,payload, check , riskType, riskTypeVerbose, severity,reference) {
    rules = append(rules, {
        "packet": packet,
        "payload": payload,
        "check": check,
        "type": riskType,
        "typeVerbose": riskTypeVerbose,
        "severity": severity,
        "reference":reference,
    })
}


//填充对应的漏洞检测规则
addRule(PacketGet,`/nifi-api/flow/current-user`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAnyOfSubString(header, `application/json`)&& str.MatchAllOfSubString(body, `"identity":"anonymous","anonymous":true"`) {
        return true
    }
    return false
},"未授权访问","apache-nifi-api-unauthorized-access","low","https://nifi.apache.org/docs/nifi-docs/rest-api/index.html")



addRule(PacketGet,`/api/v1/cluster/summary`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(body, `"totalMem":`,`"stormVersion":`) {
        return true
    }
    return false
},"未授权访问","apache-storm-unauthorized-access","low","https://storm.apache.org/releases/current/STORM-UI-REST-API.html")



addRule(PacketGet,`/pma/`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(body, `information_schema`,`phpMyAdmin`,`server_sql.php`) {
        return true
    }
    return false
},"未授权访问","bt742-pma-unauthorized-access","low","https://mp.weixin.qq.com/s/KgAaFRKarMdycYzETyKS8A")



addRule(PacketPost,`frashnum=&action=login&Frm_Logintoken=1&Username=CUAdmin&Password=CUAdmin&Username=&Password=`,func(rsp,header,body){
    if rsp.StatusCode == 302 && str.MatchAllOfSubString(header, `/menu.gch`) {
        return true
    }
    return false
},"弱口令","chinaunicom-modem-default-password","low","poc-yaml-chinaunicom-modem-default-password")


//漏洞检测handle 
handleRule = func(swg, isTls, addr, rule) {
    swg.Add()
    go func{
        defer swg.Done()

        defer func{
            recover()
        }

        resp, req, err = poc.HTTP(rule["packet"], poc.https(isTls), poc.params({"target": addr, "payload": rule.payload}),poc.redirectTimes(0))
        if err != nil {
            yakit.Error("poc.HTTP error: %v", err)
            return
        }
        header, body = poc.Split(resp)
        rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
        urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
        url = urlIns.String()
        if rule.check(rspIns, header, body) {
            yakit.Info("FOUND INFO for %v", rule.typeVerbose)
            risk.NewRisk(
                url, risk.severity(rule.severity), 
                risk.title(sprintf("FOUND %v", rule.typeVerbose)),
                risk.titleVerbose(sprintf("reference %v", rule.reference)),
                risk.type(rule.type), risk.typeVerbose(rule.typeVerbose),
                risk.payload(rule.payload), risk.details({
                    "request": req,
                    "response": resp,
                    "url": url,
                }),
            )
            return
        }
        return
    }
}



handle = func(result) {
    if !result.IsOpen() {
        return
    }

    //判断是否是http
    if len(result.Fingerprint.HttpFlows) <= 0 {
        return
    }
    addr = str.HostPort(result.Target, result.Port)
    isTls = str.IsTLSServer(str.HostPort(result.Target, result.Port))

    // 漏洞检测
    swg = sync.NewSizedWaitGroup(10)
    for _, rule = range rules {
        handleRule(swg, isTls, addr, rule)
    }
    swg.Wait()
}
